page_settings.custom_css:
/* ===== CSS base da casa (vai para page_settings.custom_css) ===== */
::selection { background-color: rgba(255, 255, 255, 0.125); }
html, body { overflow-x: hidden; }
p:last-of-type { margin-bottom: 0; }
body::-webkit-scrollbar { width: 10px; }
body::-webkit-scrollbar-track { background-color: #111111; }
body::-webkit-scrollbar-thumb { background: #fff; border-radius: 15px; border: 2px solid #111111; }

/* ===== tokens ===== */
:root { --marca: #1F4E5F; --marca-escura: #173B47; --neutro: #FAF8F5; --neutro-2: #F2EEE8; --acento: #B38A3D; --texto: #2A2A2A; --texto-2: #4A4A4A; }
body { margin: 0; font-family: Inter, sans-serif; color: var(--texto); background: var(--neutro); }
section { padding: 80px 20px; display: flex; flex-direction: column; align-items: center; }
.wrap { width: 100%; max-width: 1140px; display: flex; flex-direction: column; gap: 20px; }
.linha { display: flex; flex-direction: row; gap: 40px; align-items: center; }
.col { flex: 1; display: flex; flex-direction: column; gap: 20px; }
.rotulo { font: 600 12px/1.4 Inter, sans-serif; letter-spacing: 1.8px; text-transform: uppercase; color: var(--acento); margin: 0; }
h1, h2 { font-family: Fraunces, serif; font-weight: 400; margin: 0; }
/* títulos: até 3 linhas na coluna (4 se a frase for longa), teto 55px */
h1 { font-size: 46px; line-height: 1.1; color: var(--marca-escura); }
h2 { font-size: 40px; line-height: 1.15; color: var(--marca-escura); }
h3 { font: 600 20px/1.3 Inter, sans-serif; margin: 0; color: var(--texto); }
p { font-size: 17px; line-height: 1.7; color: var(--texto-2); margin: 0; }
em { color: var(--acento); font-style: italic; }
.btn { display: inline-block; align-self: flex-start; padding: 18px 40px; border-radius: 999px; background: linear-gradient(180deg, #2A6478 0%, #1F4E5F 100%); color: #fff; font: 500 18px/1.4 Inter, sans-serif; text-decoration: none; }
.btn-claro { background: #FAF8F5; color: #1F4E5F; }
/* hero padrão: foto de fundo com fade (IMG-01 desktop, IMG-01-mobile recorte) */
.hero { background: linear-gradient(90deg, rgba(250,248,245,.92) 0%, rgba(250,248,245,.75) 34%, rgba(250,248,245,0) 58%), url(imagens/IMG-01.webp) right center / cover no-repeat, var(--neutro); min-height: 800px; justify-content: center; }
.hero .col { max-width: 560px; }
.hero .logo { height: 52px; width: auto; align-self: flex-start; }
.card .ic { width: 48px; height: 48px; border-radius: 50%; background: var(--neutro-2); color: var(--marca); display: flex; align-items: center; justify-content: center; }
.card .ic svg { width: 22px; height: 22px; }
.cards { display: flex; flex-direction: row; gap: 20px; flex-wrap: wrap; }
.card { flex: 1 1 300px; background: #fff; border-radius: 12px; padding: 28px; display: flex; flex-direction: column; gap: 10px; box-shadow: 0px 12px 40px 0px rgba(31, 78, 95, 0.06); }
.card p { font-size: 15px; }
.alt { background: var(--neutro-2); }
.passos { display: flex; flex-direction: row; gap: 20px; }
.passo { flex: 1; display: flex; flex-direction: column; gap: 8px; }
.num { font: 400 56px/1 Fraunces, serif; color: var(--marca); margin: 0; }
details { background: #fff; border-radius: 12px; padding: 18px 22px; }
summary { font-weight: 600; cursor: pointer; }
.final { background: var(--marca-escura); }
.final h2 { color: #fff; }
.final p { color: #ffffffcc; }
footer { padding: 30px 20px; background: #111; color: #aaa; font-size: 13px; display: flex; justify-content: center; }
footer p { color: #aaa; font-size: 13px; }
@media (max-width: 767px) {
  section { padding: 50px 16px; }
  .linha, .passos { flex-direction: column; }
  h1 { font-size: 29px; }
  h2 { font-size: 26px; }
  .hero { min-height: 0; padding-top: 40vh; background: linear-gradient(180deg, rgba(250,248,245,0) 0, rgba(250,248,245,0) 38vh, rgba(250,248,245,.88) 46vh, var(--neutro) 62vh), url(imagens/IMG-01-mobile.webp) center top / 100% auto no-repeat, var(--neutro); }
  .hero .logo { height: 28px; }
  .hero .col { gap: 12px; }
  .hero p { font-size: 15px; }
  .btn { align-self: stretch; text-align: center; }
}
/* animação de entrada da casa */
.scroll-bottom { opacity: 0; transition: 0.5s all; transform: translate3d(0, 80px, 0); }
.ativo { opacity: 1; transform: translate3d(0, 0, 0); }
